<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow — Piet Mondrian, 1930</title>
<meta name="description" content="Piet Mondrian's Composition with Red, Blue and Yellow (1930): painter, year, movement and why the work matters.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;700;900&display=swap" rel="stylesheet">
<style>
  :root {
    --red: #d40920;
    --blue: #14418c;
    --yellow: #f2c500;
    --black: #111111;
    --white: #f7f5f0;
    --grey: #d9d6cf;
    --line: 10px;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { height: 100%; }
  body {
    font-family: 'Archivo', system-ui, sans-serif;
    background: var(--white);
    color: var(--black);
    overflow-x: hidden;
  }

  /* ---------- Mondrian grid layout ---------- */
  .grid {
    display: grid;
    min-height: 100vh;
    grid-template-columns: 1.1fr 0.9fr 0.7fr;
    grid-template-rows: auto auto 1fr auto;
    gap: var(--line);
    background: var(--black);
    padding: var(--line);
  }
  .cell {
    background: var(--white);
    padding: clamp(20px, 3.5vw, 48px);
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 14px;
  }
  .cell--red { background: var(--red); color: var(--white); }
  .cell--blue { background: var(--blue); color: var(--white); }
  .cell--yellow { background: var(--yellow); color: var(--black); }

  /* placement: mirror the painting */
  .cell--title   { grid-column: 1 / 3; grid-row: 1; }
  .cell--red     { grid-column: 3;     grid-row: 1 / 3; }
  .cell--facts   { grid-column: 1;     grid-row: 2; }
  .cell--move    { grid-column: 2;     grid-row: 2; }
  .cell--why     { grid-column: 1 / 3; grid-row: 3; }
  .cell--blue    { grid-column: 1;     grid-row: 4; }
  .cell--yellow  { grid-column: 2;     grid-row: 4; }
  .cell--source  { grid-column: 3;     grid-row: 3 / 5; }

  h1 {
    font-weight: 900;
    font-size: clamp(28px, 4.2vw, 56px);
    line-height: 1.02;
    letter-spacing: -0.02em;
    text-transform: uppercase;
  }
  h1 .accent { color: var(--red); }
  .subtitle {
    font-size: clamp(15px, 1.6vw, 20px);
    font-weight: 500;
    max-width: 34ch;
  }
  .kicker {
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    opacity: 0.75;
  }
  h2 {
    font-weight: 700;
    font-size: clamp(18px, 2vw, 24px);
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }
  p { font-size: clamp(14px, 1.4vw, 17px); line-height: 1.55; }
  .list { list-style: none; display: flex; flex-direction: column; gap: 8px; }
  .list li { font-size: clamp(14px, 1.4vw, 16px); line-height: 1.45; }
  .list li::before { content: "— "; opacity: 0.6; }

  a.cta {
    display: inline-block;
    align-self: flex-start;
    margin-top: 6px;
    background: var(--black);
    color: var(--white);
    text-decoration: none;
    font-weight: 700;
    font-size: 15px;
    padding: 14px 22px;
    border: 3px solid var(--black);
    transition: background 0.15s, color 0.15s;
  }
  a.cta:hover { background: var(--white); color: var(--black); }
  .cell--red a.cta { background: var(--white); color: var(--red); border-color: var(--white); }
  .cell--red a.cta:hover { background: var(--black); color: var(--white); border-color: var(--black); }

  /* ---------- 3D canvas ---------- */
  #stage {
    position: fixed;
    inset: 0;
    z-index: -1;
    opacity: 0.07;
    pointer-events: none;
  }

  @media (max-width: 760px) {
    .grid {
      grid-template-columns: 1fr;
      grid-template-rows: none;
    }
    .cell { grid-column: 1 !important; grid-row: auto !important; }
  }
</style>
</head>
